import { useEffect, useState } from "react";
import { User, UserRole } from "@/lib/auth";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  User as UserIcon,
  Shield,
  Upload,
  X,
  Loader2,
  CheckCircle2,
  Mail,
  Phone,
  Building2,
} from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

import { SYSTEM_ORG_ID } from "@/lib/constants";
import { PERMISSION_LABELS, getPermissionsByContext } from "@/lib/permissions";

type Props = {
  onOpenChange: (open: boolean) => void;
  onSave: (data: FormData) => void;
  initialData?: Partial<User>;
  isNew?: boolean;
  isLoading?: boolean;
};

export function UserForm({
  onOpenChange,
  onSave,
  initialData,
  isNew = true,
  isLoading = false,
}: Props) {
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [role, setRole] = useState<UserRole>(UserRole.SYSTEM_ADMIN);
  const [profileImage, setProfileImage] = useState<File | null>(null);
  const [permissions, setPermissions] = useState<string[]>([]);
  const [preview, setPreview] = useState<string | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (!initialData) return;
    setFullName(initialData.fullName || "");
    setEmail(initialData.email || "");
    setPhoneNumber(initialData.phoneNumber || "");
    setRole((initialData.role as UserRole) || UserRole.SYSTEM_ADMIN);
    if (
      initialData.profileImage &&
      typeof initialData.profileImage === "string"
    ) {
      setPreview(initialData.profileImage);
    }
    // Handle permissions if backend returns it as array
    if (initialData.permissions && Array.isArray(initialData.permissions)) {
      setPermissions(initialData.permissions);
    }
  }, [initialData]);

  useEffect(() => {
    if (!profileImage) return;
    const url = URL.createObjectURL(profileImage);
    setPreview(url);
    return () => URL.revokeObjectURL(url);
  }, [profileImage]);

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!fullName.trim()) newErrors.fullName = "Full name is required";
    if (!email.trim()) newErrors.email = "Email is required";
    if (!phoneNumber.trim()) newErrors.phoneNumber = "Phone number is required";
    if (!role) newErrors.role = "Role is required";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = () => {
    if (!validate()) {
      toast.error("Please fill in all required fields marked in red");
      return;
    }

    const formData = new FormData();
    formData.append("fullName", fullName);
    formData.append("email", email);
    formData.append("phoneNumber", phoneNumber);
    formData.append("role", role);
    formData.append("isStaffUser", "true");

    // Default orgId for system users
    if (role === UserRole.SYSTEM_SUPER_ADMIN || role === UserRole.SYSTEM_ADMIN) {
      formData.append("orgId", SYSTEM_ORG_ID);
    }

    if (profileImage) {
      formData.append("profileImage", profileImage);
    }

    // Add Permissions
    if (permissions.length > 0) {
      permissions.forEach(p => formData.append("permissions", p));
    }

    onSave(formData);
  };

  const togglePermission = (permission: string) => {
    setPermissions(prev =>
      prev.includes(permission)
        ? prev.filter(p => p !== permission)
        : [...prev, permission]
    );
  };

  const toggleCategory = (categoryPermissions: string[]) => {
    const allSelected = categoryPermissions.every(p => permissions.includes(p));
    if (allSelected) {
      setPermissions(prev => prev.filter(p => !categoryPermissions.includes(p)));
    } else {
      setPermissions(prev => {
        const newPerms = [...prev];
        categoryPermissions.forEach(p => {
          if (!newPerms.includes(p)) newPerms.push(p);
        });
        return newPerms;
      });
    }
  };

  return (
    <div className="fixed inset-0 z-[100] bg-white overflow-hidden flex flex-col">
      {/* Top Header */}
      <div className="flex items-center justify-between px-4 md:px-8 py-5 shrink-0 bg-white border-b shadow-sm z-20">
        <div>
          <h2 className="text-xl font-bold text-slate-900">
            {isNew ? "Create System User" : "Update User Account"}
          </h2>
          <p className="text-sm text-slate-500 font-medium mt-1">
            Manage staff access and permissions for the dashboard
          </p>
        </div>
        <Button
          variant="ghost"
          onClick={() => onOpenChange(false)}
          className="h-10 w-10 p-0 rounded-full hover:bg-primary hover:text-white text-slate-500 flex items-center justify-center border border-slate-200 shadow-sm transition-all"
        >
          <X className="h-5 w-5" />
        </Button>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-y-auto px-4 md:px-10 pb-6 bg-slate-50/30">
        <div className="max-w-7xl mx-auto h-full pt-10">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            {/* Left Column: Profile & Basic Info */}
            <div className="lg:col-span-1 space-y-6">
              {/* Profile Photo */}
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center gap-2">
                  <UserIcon className="h-5 w-5 text-primary" />
                  Profile Photo
                </h3>
                <div className="flex flex-col items-center gap-6">
                  <div className="h-48 w-48 rounded-full border-8 border-white shadow-2xl flex items-center justify-center bg-slate-200 overflow-hidden relative group cursor-pointer transition-transform hover:scale-105">
                    {preview ? (
                      <img
                        src={preview}
                        alt="Preview"
                        className="h-full w-full object-cover"
                      />
                    ) : (
                      <UserIcon className="h-20 w-20 text-slate-400" />
                    )}
                    <label
                      htmlFor="profileImage"
                      className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer"
                    >
                      <Upload className="h-10 w-10 text-white" />
                    </label>
                  </div>

                  <Label
                    htmlFor="profileImage"
                    className="cursor-pointer text-sm font-black text-primary hover:opacity-80 transition-all flex items-center gap-2 px-6 py-3 rounded-full border border-primary/20 bg-white shadow-sm"
                  >
                    <Upload className="h-4 w-4" /> Upload Photo
                  </Label>
                  <input
                    id="profileImage"
                    type="file"
                    accept="image/*"
                    className="hidden"
                    onChange={(e) =>
                      setProfileImage(e.target.files?.[0] || null)
                    }
                  />
                </div>
              </div>

              {/* Role Selection */}
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center gap-2">
                  <Shield className="h-5 w-5 text-primary" />
                  System Role
                </h3>
                <div className="space-y-4">
                  <div className="space-y-3">
                    <Label className="text-sm font-black text-slate-900">
                      Access Level *
                    </Label>
                    <Select
                      value={role}
                      onValueChange={(val) => setRole(val as UserRole)}
                    >
                      <SelectTrigger className="h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold">
                        <SelectValue placeholder="Choose Role" />
                      </SelectTrigger>
                      <SelectContent className="rounded-2xl shadow-2xl border-slate-100">
                        <SelectItem
                          value={UserRole.SYSTEM_SUPER_ADMIN}
                          className="h-12 font-bold text-primary"
                        >
                          System Super Admin
                        </SelectItem>
                        <SelectItem
                          value={UserRole.SYSTEM_ADMIN}
                          className="h-12 font-bold"
                        >
                          System Admin
                        </SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-3">
                    <Label className="text-sm font-black text-slate-900">
                      Organization
                    </Label>
                    <div className="flex items-center gap-3 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                      <Building2 className="h-5 w-5 text-slate-400" />
                      <span className="text-sm font-bold text-slate-600">PossibleTech</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Right Column: Contact Info & Permissions */}
            <div className="lg:col-span-2 space-y-6">
              {/* Contact Information */}
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <h3 className="text-lg font-black text-slate-900 mb-6">
                  Contact Information
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-3 md:col-span-2">
                    <Label className="text-sm font-black text-slate-900">
                      Full Name *
                    </Label>
                    <Input
                      className={`h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold px-4 focus:ring-2 focus:ring-primary/20 ${errors.fullName ? "border-red-500 bg-red-50" : ""}`}
                      placeholder="e.g. Samuel Ayele"
                      value={fullName}
                      onChange={(e) => {
                        setFullName(e.target.value);
                        if (errors.fullName) setErrors({ ...errors, fullName: "" });
                      }}
                    />
                    {errors.fullName && <p className="text-xs text-red-500 font-medium">{errors.fullName}</p>}
                  </div>

                  <div className="space-y-3">
                    <Label className="text-sm font-black text-slate-900 flex items-center gap-2">
                      <Mail className="h-4 w-4 text-primary" />
                      Email Address *
                    </Label>
                    <Input
                      className={`h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold px-4 focus:ring-2 focus:ring-primary/20 ${errors.email ? "border-red-500 bg-red-50" : ""}`}
                      type="email"
                      placeholder="samuel@parking-mgmt.com"
                      value={email}
                      onChange={(e) => {
                        setEmail(e.target.value);
                        if (errors.email) setErrors({ ...errors, email: "" });
                      }}
                    />
                    {errors.email && <p className="text-xs text-red-500 font-medium">{errors.email}</p>}
                  </div>

                  <div className="space-y-3">
                    <Label className="text-sm font-black text-slate-900 flex items-center gap-2">
                      <Phone className="h-4 w-4 text-primary" />
                      Phone Number *
                    </Label>
                    <Input
                      className={`h-14 w-full rounded-2xl border-slate-200 bg-white text-lg font-bold px-4 focus:ring-2 focus:ring-primary/20 ${errors.phoneNumber ? "border-red-500 bg-red-50" : ""}`}
                      placeholder="+251 9..."
                      value={phoneNumber}
                      onChange={(e) => {
                        setPhoneNumber(e.target.value);
                        if (errors.phoneNumber) setErrors({ ...errors, phoneNumber: "" });
                      }}
                    />
                    {errors.phoneNumber && <p className="text-xs text-red-500 font-medium">{errors.phoneNumber}</p>}
                  </div>
                </div>
              </div>

              {/* Permissions Section */}
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-lg font-black text-slate-900 flex items-center gap-2">
                    <Shield className="h-5 w-5 text-primary" />
                    Access Permissions
                  </h3>
                  <div className="flex items-center gap-2 text-sm">
                    <span className="font-bold text-slate-500">{permissions.length} selected</span>
                  </div>
                </div>

                <div className="mb-6 p-4 bg-blue-50 border border-blue-200 rounded-2xl">
                  <p className="text-xs text-blue-800 font-bold flex items-center gap-2">
                    <Shield className="h-4 w-4" />
                    {role === UserRole.PARKING_SUPER_ADMIN || role === UserRole.PARKING_MANAGER
                      ? "Showing parking-specific permissions only."
                      : "Showing all system permissions."}
                  </p>
                </div>

                <div className="space-y-6">
                  {Object.entries(
                    getPermissionsByContext(
                      role === UserRole.PARKING_SUPER_ADMIN || role === UserRole.PARKING_MANAGER
                    )
                  ).map(([category, categoryPermissions]) => {
                    const permArray = categoryPermissions as string[];
                    const allSelected = permArray.every(p => permissions.includes(p));
                    const someSelected = permArray.some(p => permissions.includes(p));

                    return (
                      <div key={category} className="border border-slate-100 rounded-2xl overflow-hidden">
                        <div
                          className={cn(
                            "flex items-center justify-between p-4 cursor-pointer transition-colors",
                            allSelected ? "bg-primary/5 border-b border-primary/10" : "bg-slate-50 border-b border-slate-100"
                          )}
                          onClick={() => toggleCategory(permArray)}
                        >
                          <div className="flex items-center gap-3">
                            <div
                              className={cn(
                                "h-5 w-5 rounded border-2 flex items-center justify-center transition-all",
                                allSelected
                                  ? "bg-primary border-primary"
                                  : someSelected
                                    ? "bg-primary/20 border-primary"
                                    : "border-slate-300"
                              )}
                            >
                              {allSelected && <CheckCircle2 className="h-3 w-3 text-white" />}
                              {someSelected && !allSelected && <div className="h-2 w-2 bg-primary rounded-sm" />}
                            </div>
                            <span className="font-black text-slate-900">{category}</span>
                          </div>
                          <span className="text-xs font-bold text-slate-400">
                            {permArray.filter(p => permissions.includes(p)).length}/{permArray.length}
                          </span>
                        </div>

                        <div className="p-4 bg-white space-y-2">
                          {permArray.map((permission: string) => {
                            const isChecked = permissions.includes(permission);
                            return (
                              <div
                                key={permission}
                                className={cn(
                                  "flex items-center space-x-3 p-3 rounded-xl transition-all cursor-pointer",
                                  isChecked ? "bg-primary/5 border border-primary/10" : "hover:bg-slate-50"
                                )}
                                onClick={() => togglePermission(permission)}
                              >
                                <input
                                  type="checkbox"
                                  id={permission}
                                  className="h-5 w-5 rounded border-slate-300 text-primary focus:ring-primary/20 cursor-pointer"
                                  checked={isChecked}
                                  onChange={() => { }}
                                  onClick={(e) => e.stopPropagation()}
                                />
                                <label
                                  htmlFor={permission}
                                  className="text-sm font-bold text-slate-700 cursor-pointer select-none flex-1"
                                >
                                  {PERMISSION_LABELS[permission]}
                                </label>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    );
                  })}
                </div>

                <div className="mt-6 p-4 bg-amber-50 border border-amber-200 rounded-2xl">
                  <p className="text-xs text-amber-800 font-bold flex items-center gap-2">
                    <Shield className="h-4 w-4" />
                    System Super Admins have full access to all features by default.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Footer Navigation */}
      <div className="border-t py-6 px-4 md:px-10 bg-white shrink-0 shadow-lg">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="text-sm text-slate-500 font-medium">
            {permissions.length > 0 && (
              <span className="text-primary font-bold">{permissions.length} permissions</span>
            )} selected
          </div>
          <div className="flex items-center gap-4">
            <Button
              variant="ghost"
              onClick={() => onOpenChange(false)}
              className="h-14 px-8 rounded-xl font-bold text-slate-400 hover:text-slate-900"
            >
              Cancel
            </Button>

            <Button
              onClick={handleSubmit}
              disabled={isLoading}
              className="h-14 px-16 rounded-xl bg-primary hover:opacity-90 text-white font-bold transition-all min-w-[160px] shadow-lg shadow-primary/10"
            >
              {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isNew ? "Create User" : "Update User"}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}
